AssistantMessageToolRequest(name='create', tool_call_id='tooluse_PKyJZe2TpAhf4c31VyJOh1', arguments={'file_text': 'const quizForm = document.getElementById('quizForm');
const resultDiv = document.getElementById('result');
const resultContent = document.getElementById('resultContent');

const correctAnswers = {
    q1: ['python', 'javascript'],
    q2: ['html', 'css'],
    q3: ['python', 'cpp', 'javascript']
};

quizForm.addEventListener('submit', function(event) {
    event.preventDefault();
    evaluateQuiz();
});

function getSelectedAnswers() {
    const answers = {};

    for (const question in correctAnswers) {
        const checkboxes = document.querySelectorAll(`input[name="${question}"]:checked`);
        answers[question] = Array.from(checkboxes).map(checkbox => checkbox.value);
    }

    return answers;
}

function evaluateQuiz() {
    const userAnswers = getSelectedAnswers();
    let totalCorrect = 0;
    let totalQuestions = Object.keys(correctAnswers).length;

    let html = '';

    for (const question in correctAnswers) {
        const correctSet = new Set(correctAnswers[question]);
        const userSet = new Set(userAnswers[question]);

        const isCorrect = 
            correctSet.size === userSet.size && 
            [...correctSet].every(answer => userSet.has(answer));

        if (isCorrect) {
            totalCorrect++;
        }

        const questionNumber = question.charAt(1);
        const status = isCorrect ? 'correct' : 'incorrect';
        const statusIcon = isCorrect ? '✓' : '✗';
        const statusText = isCorrect ? 'Correct' : 'Incorrect';

        html += `
            <div class="result-item ${status}">
                <div class="result-item-title">
                    ${statusIcon} Question ${questionNumber}: ${statusText}
                </div>
                <div class="result-item-details">
                    <strong>Correct answer(s):</strong> ${correctAnswers[question].join(', ')}<br>
                    <strong>Your answer(s):</strong> ${userAnswers[question].length > 0 ? userAnswers[question].join(', ') : '(none selected)'}
                </div>
            </div>
        `;
    }

    const percentage = Math.round((totalCorrect / totalQuestions) * 100);
    const scoreHTML = `
        <div style="margin-bottom: 24px; padding: 16px; background-color: rgba(138, 180, 248, 0.1); border-radius: 6px; text-align: center;">
            <div style="font-size: 28px; font-weight: 600; color: var(--accent-color);">${totalCorrect}/${totalQuestions}</div>
            <div style="color: var(--text-secondary); margin-top: 4px;">You got ${percentage}% correct</div>
        </div>
    `;

    resultContent.innerHTML = scoreHTML + html;

    quizForm.style.display = 'none';
    resultDiv.style.display = 'block';

    window.scrollTo({ top: 0, behavior: 'smooth' });
}

function resetQuiz() {
    quizForm.reset();
    resultDiv.style.display = 'none';
    quizForm.style.display = 'block';
    window.scrollTo({ top: 0, behavior: 'smooth' });
}
