    margin-bottom: 36px;
    padding: 24px;
    background-color: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    transition: background-color 0.2s ease, border-color 0.2s ease;
}

.form-field:hover {
    background-color: var(--bg-tertiary);
    border-color: var(--accent-color);
}

.question-label {
    display: block;
    font-size: 16px;
    font-weight: 500;
    margin-bottom: 12px;
    cursor: pointer;
}

.question-number {
    color: var(--accent-color);
    font-weight: 600;
    margin-right: 8px;
}

.help-text {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    background-color: rgba(138, 180, 248, 0.08);
    border-left: 3px solid var(--accent-color);
    padding: 12px;
    margin-bottom: 16px;
    border-radius: 4px;
    font-size: 14px;
    color: var(--text-secondary);
}

.help-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 20px;
    height: 20px;
    color: var(--accent-color);
    font-weight: bold;
}

.options-group {
    display: flex;
    flex-direction: column;
    gap: 12px;
    border: none;
}

.option {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px;
    background-color: var(--bg-tertiary);
    border: 1px solid var(--border-color);
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.2s ease;
}

.option:hover {
    background-color: rgba(138, 180, 248, 0.1);
    border-color: var(--accent-color);
}

.option input[type="checkbox"] {
    appearance: none;
    -webkit-appearance: none;
    width: 0;
    height: 0;
    opacity: 0;
    position: absolute;
    cursor: pointer;
}

.checkbox-custom {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 20px;
    height: 20px;
    min-width: 20px;
    border: 2px solid var(--border-color);
    border-radius: 4px;
    background-color: transparent;
    transition: all 0.2s ease;
}

.option input[type="checkbox"]:checked + .checkbox-custom {
    background-color: var(--accent-color);
    border-color: var(--accent-color);
}

.option input[type="checkbox"]:checked + .checkbox-custom::after {
    content: '✓';
    color: var(--bg-primary);
    font-weight: bold;
    font-size: 14px;
}

.option input[type="checkbox"]:focus + .checkbox-custom {
    border-color: var(--focus-color);
    box-shadow: 0 0 0 3px rgba(138, 180, 248, 0.25);
}

.option span:last-child {
    flex: 1;
    color: var(--text-primary);
    font-weight: 500;
}

.submit-btn {
    width: 100%;
    padding: 14px 24px;
    background-color: var(--accent-color);
    color: var(--bg-primary);
