.result-item {
    margin-bottom: 20px;
    padding: 16px;
    background-color: var(--bg-tertiary);
    border-radius: 6px;
    border-left: 4px solid var(--border-color);
}

.result-item.correct {
    border-left-color: var(--success-color);
}

.result-item.incorrect {
    border-left-color: var(--error-color);
}

.result-item-title {
    font-weight: 600;
    margin-bottom: 8px;
    display: flex;
    align-items: center;
    gap: 8px;
}

.result-item.correct .result-item-title {
    color: var(--success-color);
}

.result-item.incorrect .result-item-title {
    color: var(--error-color);
}

.result-item-details {
    font-size: 14px;
    color: var(--text-secondary);
    line-height: 1.5;
}

.reset-btn {
    width: 100%;
    padding: 12px 24px;
    background-color: var(--bg-tertiary);
    color: var(--accent-color);
    border: 1px solid var(--accent-color);
    border-radius: 6px;
    font-size: 16px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
    margin-top: 16px;
}

.reset-btn:hover {
    background-color: rgba(138, 180, 248, 0.1);
}

.reset-btn:focus {
    outline: none;
    box-shadow: 0 0 0 3px rgba(138, 180, 248, 0.25);
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

